<?php
namespace App\Controllers;use App\Core\Database;use App\Core\Security;use App\Core\Auth;
final class TransactionController{public function index():void{$db=Database::connection();$rows=$db->query('SELECT c.*,b.title,u.name user_name FROM checkouts c JOIN books b ON b.id=c.book_id JOIN users u ON u.id=c.user_id ORDER BY c.checked_out_at DESC')->fetchAll();$title='Check In and Check Out';require BASE_PATH.'/app/Views/transactions/index.php';}public function checkout():void{Auth::requireRole(['administrator','librarian','staff']);$db=Database::connection();if($_SERVER['REQUEST_METHOD']==='POST'&&Security::validCsrf($_POST['_csrf']??null)){$db->beginTransaction();$s=$db->prepare('INSERT INTO checkouts(book_id,user_id,borrower_name,borrower_id,due_date) VALUES(?,?,?,?,?)');$s->execute([(int)$_POST['book_id'],Auth::user()['id'],trim($_POST['borrower_name']),trim($_POST['borrower_id']),$_POST['due_date']]);$db->prepare('UPDATE books SET available_quantity=available_quantity-1 WHERE id=? AND available_quantity>0')->execute([(int)$_POST['book_id']]);$db->commit();Security::flash('success','Book checked out successfully.');Security::redirect('transactions');}$books=$db->query('SELECT id,title,available_quantity FROM books WHERE available_quantity>0 ORDER BY title')->fetchAll();$title='Check Out Book';require BASE_PATH.'/app/Views/transactions/form.php';}public function checkin():void{if(!Security::validCsrf($_POST['_csrf']??null)){Security::flash('danger','Request expired.');Security::redirect('transactions');}$db=Database::connection();$s=$db->prepare('SELECT * FROM checkouts WHERE id=? AND status="checked_out"');$s->execute([(int)$_POST['id']]);$r=$s->fetch();if($r){$fine=max(0,(int)((strtotime(date('Y-m-d'))-strtotime($r['due_date']))/86400))*10;$db->prepare('UPDATE checkouts SET returned_at=NOW(),status="returned",fine=? WHERE id=?')->execute([$fine,$r['id']]);$db->prepare('UPDATE books SET available_quantity=available_quantity+1 WHERE id=?')->execute([$r['book_id']]);Security::flash('success','Book checked in. Fine: ₱'.number_format($fine,2));}Security::redirect('transactions');}public function markCondition():void{if(!Security::validCsrf($_POST['_csrf']??null)){Security::flash('danger','Request expired.');Security::redirect('transactions');}$db=Database::connection();$s=$db->prepare('SELECT book_id FROM checkouts WHERE id=?');$s->execute([(int)$_POST['id']]);$book=$s->fetchColumn();$db->prepare('UPDATE checkouts SET status=?,notes=? WHERE id=?')->execute([$_POST['condition'],trim($_POST['notes']??''),(int)$_POST['id']]);if($book)$db->prepare('UPDATE books SET condition_status=?,available_quantity=GREATEST(available_quantity-1,0) WHERE id=?')->execute([$_POST['condition']==='lost'?'lost':'damaged',$book]);Security::flash('success','Book condition updated.');Security::redirect('transactions');}}
